import {AbsoluteFill, Audio, Sequence, Series, interpolate, staticFile} from 'remotion';
import {theme} from './theme';
import {Title} from './scenes/Title';
import {TerminalScene} from './scenes/TerminalScene';
import {ProvidersGrid} from './scenes/ProvidersGrid';
import {Closing} from './scenes/Closing';
// Generated by `just sizzle-tapes` (ffprobe). Lets each clip be sped up to
// exactly fit its scene slot.
import clipDurations from './clip-durations.json';
// Generated by promo/generate_voices.py — every provider says its own line.
import {duckFactor, voiceCues} from './voiceSchedule';

const clipSeconds = (name: keyof typeof clipDurations): number => clipDurations[name];

// 900 frames total (30s @ 30fps). Scene lengths must sum to 900 and scene
// starts must match SCENES in voiceSchedule.ts.
// `music` is set by `just sizzle-render` based on whether
// public/music.mp3 exists (generated by promo/generate_music.py).
export const SizzleReel: React.FC<{music?: boolean}> = ({music = false}) => {
  return (
    <AbsoluteFill style={{backgroundColor: theme.bg}}>
      {music ? (
        <Audio
          src={staticFile('music.mp3')}
          volume={(f) =>
            // Base envelope, ducked under provider voice lines.
            interpolate(f, [0, 20, 840, 900], [0, 0.55, 0.55, 0], {
              extrapolateLeft: 'clamp',
              extrapolateRight: 'clamp',
            }) * duckFactor(f)
          }
        />
      ) : null}
      {voiceCues.map((cue) => (
        <Sequence key={cue.id} from={cue.from} durationInFrames={cue.durationInFrames + 15}>
          <Audio src={staticFile(cue.file)} />
        </Sequence>
      ))}
      <Series>
        <Series.Sequence durationInFrames={60}>
          <Title />
        </Series.Sequence>

        <Series.Sequence durationInFrames={150}>
          <TerminalScene
            clip="clips/01-say.mp4"
            clipSeconds={clipSeconds('01-say.mp4')}
            kicker="Drop-in replacement"
            headline="Starts where macOS `say` leaves off"
            accent={theme.accent}
          />
        </Series.Sequence>

        <Series.Sequence durationInFrames={270}>
          <ProvidersGrid />
        </Series.Sequence>

        <Series.Sequence durationInFrames={150}>
          <TerminalScene
            clip="clips/02-gemini.mp4"
            clipSeconds={clipSeconds('02-gemini.mp4')}
            kicker="New in 0.10"
            headline="Gemini TTS — 30 voices, multi-speaker dialogue"
            accent={theme.accent4}
          />
        </Series.Sequence>

        <Series.Sequence durationInFrames={186}>
          <TerminalScene
            clip="clips/03-daemon.mp4"
            clipSeconds={clipSeconds('03-daemon.mp4')}
            kicker="Local · free · SOTA open models"
            headline="Warm daemon + VibeVoice — ~2.5× faster than realtime"
            accent={theme.accent2}
          />
        </Series.Sequence>

        <Series.Sequence durationInFrames={84}>
          <Closing />
        </Series.Sequence>
      </Series>
    </AbsoluteFill>
  );
};
